const express = require('express');
const jwt = require('jsonwebtoken');

const app = express();

const secretKey = process.env.DOCUSEAL_API_KEY;

app.post('/api/docuseal/builder_token', (req, res) => {
  const token = jwt.sign({
    user_email: 'your-docuseal-user-email@company.com',
    integration_email: 'customer@example.com', // replace with current user email
    name: 'Integration W-9 Test Form',
    document_urls: ['https://www.irs.gov/pub/irs-pdf/fw9.pdf'],
  }, secretKey);

  res.json({ token });
});

app.listen(8080, () => {
  console.log(`Server is running`);
});

import DocusealForm from "./form";
import DocusealBuilder from "./builder";

export { DocusealForm, DocusealBuilder };

import { defineComponent, h } from "vue";

export default defineComponent({
  name: "DocusealForm",
  props: {
    src: {
      type: String,
      required: false,
      default: "",
    },
    token: {
      type: String,
      required: false,
      default: "",
    },
    host: {
      type: String,
      required: false,
      default: "cdn.docuseal.com",
    },
    role: {
      type: String,
      required: false,
      default: "",
    },
    logo: {
      type: String,
      required: false,
      default: "",
    },
    language: {
      type: String,
      required: false,
      default: "",
    },
    // Backward compatibility
    submitter: {
      type: String,
      required: false,
      default: "",
    },
    expand: {
      type: Boolean,
      required: false,
      default: true,
    },
    orderAsOnPage: {
      type: Boolean,
      required: false,
      default: false,
    },
    minimize: {
      type: Boolean,
      required: false,
      default: false,
    },
    preview: {
      type: Boolean,
      required: false,
      default: false,
    },
    dryRun: {
      type: Boolean,
      required: false,
      default: false,
    },
    email: {
      type: String,
      required: false,
      default: "",
    },
    name: {
      type: String,
      required: false,
      default: "",
    },
    backgroundColor: {
      type: String,
      required: false,
      default: "",
    },
    applicationKey: {
      type: String,
      required: false,
      default: "",
    },
    externalId: {
      type: String,
      required: false,
      default: "",
    },
    completedRedirectUrl: {
      type: String,
      required: false,
      default: "",
    },
    withTitle: {
      type: Boolean,
      required: false,
      default: true,
    },
    withDecline: {
      type: Boolean,
      required: false,
      default: false,
    },
    withFieldNames: {
      type: Boolean,
      required: false,
      default: true,
    },
    withFieldPlaceholder: {
      type: Boolean,
      required: false,
      default: false,
    },
    withSendCopyButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    withCompleteButton: {
      type: Boolean,
      required: false,
      default: false,
    },
    sendCopyEmail: {
      type: Boolean,
      required: false,
      default: null,
    },
    withDownloadButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    onlyRequiredFields: {
      type: Boolean,
      required: false,
      default: false,
    },
    allowToResubmit: {
      type: Boolean,
      required: false,
      default: true,
    },
    allowTypedSignature: {
      type: Boolean,
      required: false,
      default: true,
    },
    signature: {
      type: String,
      required: false,
      default: '',
    },
    rememberSignature: {
      type: Boolean,
      required: false,
      default: false,
    },
    reuseSignature: {
      type: Boolean,
      required: false,
      default: true,
    },
    completedMessage: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    completedButton: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    goToLast: {
      type: Boolean,
      required: false,
      default: true,
    },
    skipFields: {
      type: Boolean,
      required: false,
      default: false,
    },
    autoscrollFields: {
      type: Boolean,
      required: false,
      default: true,
    },
    values: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    i18n: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    metadata: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    fields: {
      type: Array,
      required: false,
      default: () => [],
    },
    readonlyFields: {
      type: Array,
      required: false,
      default: () => [],
    },
    customCss: {
      type: String,
      required: false,
      default: "",
    },
  },
  emits: ["complete", "init", "load", "decline"],
  mounted() {
    const scriptId = "docuseal-form-script";

    if (!document.getElementById(scriptId)) {
      const script = document.createElement("script");

      script.id = scriptId;
      script.async = true;
      script.src = `https://${this.host}/js/form.js`;

      document.head.appendChild(script);
    }

    this.$el.addEventListener("completed", (e: CustomEvent) => {
      this.$emit("complete", e.detail);
    });

    this.$el.addEventListener("declined", (e: CustomEvent) => {
      this.$emit("decline", e.detail);
    });

    this.$el.addEventListener("load", (e: CustomEvent) => {
      this.$emit("load", e.detail);
    });

    this.$el.addEventListener("init", () => {
      this.$emit("init");
    });
  },
  render() {
    return h("docuseal-form", {
      "data-src": this.src,
      "data-token": this.token,
      "data-email": this.email,
      "data-name": this.name,
      "data-role": this.role || this.submitter,
      "data-expand": this.expand,
      "data-order-as-on-page": this.orderAsOnPage,
      "data-minimize": this.minimize,
      "data-preview": this.preview,
      "data-dry-run": this.dryRun,
      "data-go-to-last": this.goToLast,
      "data-with-title": this.withTitle,
      "data-with-decline": this.withDecline,
      "data-logo": this.logo,
      "data-language": this.language,
      "data-with-field-names": this.withFieldNames,
      "data-with-field-placeholder": this.withFieldPlaceholder,
      "data-external-id": this.externalId || this.applicationKey,
      "data-completed-redirect-url": this.completedRedirectUrl,
      "data-with-download-button": this.withDownloadButton,
      "data-only-required-fields": this.onlyRequiredFields,
      "data-allow-to-resubmit": this.allowToResubmit,
      "data-allow-typed-signature": this.allowTypedSignature,
      "data-signature": this.signature,
      "data-remember-signature": this.rememberSignature,
      "data-reuse-signature": this.reuseSignature,
      "data-with-send-copy-button": this.withSendCopyButton,
      "data-with-complete-button": this.withCompleteButton,
      "data-send-copy-email": this.sendCopyEmail,
      "data-skip-fields": this.skipFields,
      "data-autoscroll-fields": this.autoscrollFields,
      "data-values": JSON.stringify(this.values),
      "data-i18n": JSON.stringify(this.i18n),
      "data-metadata": JSON.stringify(this.metadata),
      "data-fields": JSON.stringify(this.fields),
      "data-readonly-fields": this.readonlyFields.join(","),
      "data-completed-message-title": this.completedMessage.title,
      "data-completed-message-body": this.completedMessage.body,
      "data-completed-button-title": this.completedButton.title,
      "data-completed-button-url": this.completedButton.url,
      "data-background-color": this.backgroundColor,
      "data-custom-css": this.customCss,
    });
  },
});

import { defineComponent, h } from "vue";

export default defineComponent({
  name: "DocusealBuilder",
  props: {
    token: {
      type: String,
      required: true,
    },
    host: {
      type: String,
      required: false,
      default: "cdn.docuseal.com",
    },
    language: {
      type: String,
      required: false,
      default: "en",
    },
    preview: {
      type: Boolean,
      required: false,
      default: false,
    },
    previewMode: {
      type: Boolean,
      required: false,
      default: false,
    },
    inputMode: {
      type: Boolean,
      required: false,
      default: false,
    },
    autosave: {
      type: Boolean,
      required: false,
      default: true,
    },
    fields: {
      type: Array,
      required: false,
      default: () => [],
    },
    submitters: {
      type: Array,
      required: false,
      default: () => [],
    },
    requiredFields: {
      type: Array,
      required: false,
      default: () => [],
    },
    i18n: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    roles: {
      type: Array,
      required: false,
      default: () => [],
    },
    fieldTypes: {
      type: Array,
      required: false,
      default: () => [],
    },
    dateFormats: {
      type: Array,
      required: false,
      default: () => [],
    },
    drawFieldType: {
      type: String,
      required: false,
      default: "text",
    },
    withRecipientsButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    withTitle: {
      type: Boolean,
      required: false,
      default: true,
    },
    withSendButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    withSignatureId: {
      type: Boolean,
      required: false,
      default: null,
    },
    onlyDefinedFields: {
      type: Boolean,
      required: false,
      default: false,
    },
    withUploadButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    withAddPageButton: {
      type: Boolean,
      required: false,
      default: false,
    },
    withSignYourselfButton: {
      type: Boolean,
      required: false,
      default: true,
    },
    withDocumentsList: {
      type: Boolean,
      required: false,
      default: true,
    },
    withDynamicDocuments: {
      type: Boolean,
      required: false,
      default: false,
    },
    withFieldsList: {
      type: Boolean,
      required: false,
      default: true,
    },
    withFieldsDetection: {
      type: Boolean,
      required: false,
      default: false,
    },
    withFieldPlaceholder: {
      type: Boolean,
      required: false,
      default: false,
    },
    withPrefillable: {
      type: Boolean,
      required: false,
      default: false,
    },
    withRevisions: {
      type: Boolean,
      required: false,
      default: false,
    },
    withCustomFieldsTab: {
      type: Boolean,
      required: false,
      default: false,
    },
    customButton: {
      type: Object,
      required: false,
      default: () => ({ title: "", url: "" }),
    },
    emailMessage: {
      type: Object,
      required: false,
      default: () => ({ subject: "", body: "" }),
    },
    sendButtonText: {
      type: String,
      required: false,
      default: "",
    },
    saveButtonText: {
      type: String,
      required: false,
      default: "",
    },
    backgroundColor: {
      type: String,
      required: false,
      default: "",
    },
    customCss: {
      type: String,
      required: false,
      default: "",
    },
  },
  emits: ["load", "upload", "send", "init", "change", "save"],
  mounted() {
    const scriptId = "docuseal-builder-script";

    if (!document.getElementById(scriptId)) {
      const script = document.createElement("script");

      script.id = scriptId;
      script.async = true;
      script.src = `https://${this.host}/js/builder.js`;

      document.head.appendChild(script);
    }

    this.$el.addEventListener("load", (e: CustomEvent) =>
      this.$emit("load", e.detail),
    );

    this.$el.addEventListener("upload", (e: CustomEvent) =>
      this.$emit("upload", e.detail),
    );

    this.$el.addEventListener("send", (e: CustomEvent) =>
      this.$emit("send", e.detail),
    );

    this.$el.addEventListener("save", (e: CustomEvent) =>
      this.$emit("save", e.detail),
    );

    this.$el.addEventListener("change", (e: CustomEvent) =>
      this.$emit("change", e.detail),
    );

    this.$el.addEventListener("init", () => this.$emit("init"));
  },
  render() {
    return h("docuseal-builder", {
      "data-token": this.token,
      "data-preview": this.preview || this.previewMode,
      "data-input-mode": this.inputMode,
      "data-language": this.language,
      "data-autosave": this.autosave,
      "data-send-button-text": this.sendButtonText,
      "data-save-button-text": this.saveButtonText,
      "data-roles": this.roles.join(","),
      "data-field-types": this.fieldTypes.join(","),
      "data-draw-field-type": this.drawFieldType,
      "data-fields": JSON.stringify(this.fields),
      "data-submitters": JSON.stringify(this.submitters),
      "data-required-fields": JSON.stringify(this.requiredFields),
      "data-date-formats": this.dateFormats.join(","),
      "data-background-color": this.backgroundColor,
      "data-custom-button-title": this.customButton.title,
      "data-custom-button-url": this.customButton.url,
      "data-email-subject": this.emailMessage.subject,
      "data-email-body": this.emailMessage.body,
      "data-with-recipients-button": this.withRecipientsButton,
      "data-with-send-button": this.withSendButton,
      "data-with-title": this.withTitle,
      "data-with-i18n": this.i18n,
      "data-only-defined-fields": this.onlyDefinedFields,
      "data-with-upload-button": this.withUploadButton,
      "data-with-add-page-button": this.withAddPageButton,
      "data-with-documents-list": this.withDocumentsList,
      "data-with-dynamic-documents": this.withDynamicDocuments,
      "data-with-fields-list": this.withFieldsList,
      "data-with-fields-detection": this.withFieldsDetection,
      "data-with-signature-id": this.withSignatureId,
      "data-with-field-placeholder": this.withFieldPlaceholder,
      "data-with-prefillable": this.withPrefillable,
      "data-with-revisions": this.withRevisions,
      "data-with-custom-fields-tab": this.withCustomFieldsTab,
      "data-with-sign-yourself-button": this.withSignYourselfButton,
      "data-custom-css": this.customCss,
    });
  },
});
